def depth_first_reachable(board, start, goal):
    width = len(board[0])
    height = len(board)
    stack = [start]
    visited = {start[1] * width + start[0]: True}
    while len(stack) > 0:
        cell = stack.pop()
        if cell == goal:
            return True
        for delta in [[0, -1], [1, 0], [0, 1], [-1, 0]]:
            x = cell[0] + delta[0]
            y = cell[1] + delta[1]
            if x < 0 or x >= width or y < 0 or y >= height:
                continue
            key = y * width + x
            if board[y][x] == "." and key not in visited:
                visited[key] = True
                stack.append([x, y])
    return False

